def transform(grid):
    from math import gcd
    from functools import reduce

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    cells8 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not cells8:
        return out

    r0 = min(r for r, c in cells8)
    r1 = max(r for r, c in cells8)
    c0 = min(c for r, c in cells8)
    c1 = max(c for r, c in cells8)

    runs = []
    for r in range(r0, r1 + 1):
        lengths = []
        n = 0
        for c in range(c0, c1 + 1):
            if grid[r][c] == 8:
                n += 1
            elif n:
                lengths.append(n)
                n = 0
        if n:
            lengths.append(n)
        runs.extend(lengths)

    for c in range(c0, c1 + 1):
        n = 0
        for r in range(r0, r1 + 1):
            if grid[r][c] == 8:
                n += 1
            elif n:
                runs.append(n)
                n = 0
        if n:
            runs.append(n)

    size = reduce(gcd, runs) if runs else 1

    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 8)]
    if not markers:
        return out
    mr0 = min(r for r, c, v in markers)
    mr1 = max(r for r, c, v in markers)
    mc0 = min(c for r, c, v in markers)
    mc1 = max(c for r, c, v in markers)

    # Rotate the marker pattern 90 degrees clockwise.
    rh, rw = mr1 - mr0 + 1, mc1 - mc0 + 1
    rotated = [[0] * rh for _ in range(rw)]
    for r, c, v in markers:
        rotated[c - mc0][rh - 1 - (r - mr0)] = v

    for tr in range(rw):
        for tc in range(rh):
            color = rotated[tr][tc]
            if color == 0:
                continue
            for dr in range(size):
                for dc in range(size):
                    r = r0 + tr * size + dr
                    c = c0 + tc * size + dc
                    if r < h and c < w and grid[r][c] == 8:
                        out[r][c] = color
    return out
